    if (secs <= 0) return MIN_DELAY;
    return Math.max(MIN_DELAY, secs);
  }
  const t = Date.parse(s);
  if (!isNaN(t)) {
    const secs = Math.ceil((t - Date.now()) / 1000);
    if (!isFinite(secs) || secs <= 0) return MIN_DELAY;
    return Math.max(MIN_DELAY, secs);
  }
  return MIN_DELAY;
}
let delay = 0;
for (const i of rateLimitedIdx) {
  const headers = (responses[i].json && responses[i].json.headers) || {};
  const raKey = Object.keys(headers).find((k) => String(k).toLowerCase() === 'retry-after');
  delay = Math.max(delay, parseRetryAfter(raKey !== undefined ? headers[raKey] : undefined));
}
if (!Number.isInteger(delay) || delay <= 0) delay = MIN_DELAY;

// Single summary item carries the ORIGINAL decisions + next attempt into the
// next round (through Wait for Plane Retry -> Prepare Lookup Attempt).
return [
  {
    json: {
      ready: false,
      __planeLookupRetry: true,
      attempt: attempt + 1,
      retryDelaySeconds: delay,
      batchSize,
      issueKeys: keys,
      decisions: preparedItems.map((p) => p.originalDecision),
    },
  },
];

// Barrier stage 5: ALL reads succeeded — expand the fresh FINAL-round work
// items with the EXACT original decision embedded under __originalDecision.
// Apply Guards consumes the embedded decision; guard semantics are unchanged.
// This node runs once per successful barrier and releases the whole batch
// together — never a subset, never an index-match against a partial list.
const items = $input.all();
if (!items.length) throw new Error('Unwrap Lookup Batch: no items');
const first = items[0].json || {};
if (first.ready !== true) {
  throw new Error('Unwrap Lookup Batch: reached without a successful classification');
}
const batchSize = first.batchSize;
const attempt = first.attempt;
if (items.length !== batchSize) {
  throw new Error(`Unwrap Lookup Batch: expected ${batchSize} items, got ${items.length}`);
}
