if (new Set(keys).size !== keys.length) {
  throw new Error('Unwrap Lookup Batch: duplicate issueKey in released batch');
}
const out = [];
for (let i = 0; i < items.length; i++) {
  const it = items[i].json || {};
  if (it.attempt !== attempt || it.batchSize !== batchSize) {
    throw new Error('Unwrap Lookup Batch: attempt/batchSize mismatch across released batch');
  }
  const body = it.workItem || {};
  const decision = it.originalDecision;
  if (!decision || decision.issueKey !== it.issueKey) {
    throw new Error(`Unwrap Lookup Batch: decision missing or issueKey mismatch for ${it.issueKey}`);
  }
  if (!decision.issueKey || !decision.targetStateUuid || !decision.externalId || !decision.commentHtml) {
    throw new Error(`Unwrap Lookup Batch: malformed decision for ${it.issueKey}: missing required fields`);
  }
  if (!body.id || !body.project || !body.state) {
    throw new Error(`Unwrap Lookup Batch: malformed work item for ${it.issueKey}: missing id/project/state`);
  }
  out.push({
    json: { ...body, __originalDecision: decision },
    pairedItem: { item: i },
  });
}
return out;
